<template><EnterpriseAuthShell><div class="auth-panel"><h2>重置密码</h2><p class="subtitle">设置至少 12 个字符的新密码</p><el-alert v-if="!token" title="重置链接缺少令牌" type="error" :closable="false" class="mb"/><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="新密码" prop="password"><el-input v-model="form.password" type="password" show-password size="large" :prefix-icon="Lock" /></el-form-item><el-form-item label="确认新密码" prop="confirm"><el-input v-model="form.confirm" type="password" show-password size="large" :prefix-icon="Lock" /></el-form-item><el-button type="primary" size="large" :disabled="!token" :loading="loading" @click="submit">重置密码</el-button><div class="auth-links"><RouterLink to="/enterprise/login">返回登录</RouterLink></div></el-form></div></EnterpriseAuthShell></template>
<script setup lang="ts">import { reactive,ref } from 'vue';import { RouterLink,useRoute,useRouter } from 'vue-router';import type { FormInstance,FormRules } from 'element-plus';import { ElMessage } from 'element-plus';import { Lock } from '@element-plus/icons-vue';import EnterpriseAuthShell from '@/components/enterprise/EnterpriseAuthShell.vue';import { enterpriseAPI } from '@/api/enterprise';import { validatePassword } from '@/features/enterprise/validation';const route=useRoute(),router=useRouter(),token=typeof route.query.token==='string'?route.query.token:'',formRef=ref<FormInstance>(),loading=ref(false),error=ref(''),form=reactive({password:'',confirm:''});const rules:FormRules={password:[{validator:(_r,_v,cb)=>{const message=validatePassword(form.password);message?cb(new Error(message)):cb()},trigger:'blur'}],confirm:[{validator:(_r,_v,cb)=>form.confirm===form.password?cb():cb(new Error('两次输入的密码不一致')),trigger:'blur'}]};async function submit(){if(!await formRef.value?.validate().catch(()=>false))return;loading.value=true;error.value='';try{await enterpriseAPI.resetPassword(token,form.password);ElMessage.success('密码已重置');await router.replace('/enterprise/login')}catch(e){error.value=(e as{message?:string}).message||'重置失败'}finally{loading.value=false}}</script><style scoped>.mb{margin-bottom:20px}</style>
